                  "text": "1.600 weitere Unterstützerinnen und Unterstützer für das Bauhaus-Manifest — Staatsminister Weimer: „Großer Erfolg für die Prinzipien von Freiheit, Offenheit und Innovation“",
                  "href": "https://www.bundesregierung.de/breg-de/aktuelles/1-600-weitere-unterstuetzerinnen-und-unterstuetzer-fuer-das-bauhaus-manifest-staatsminister-weimer-grosser-erfolg-fuer-die-prinzipien-von-freiheit-offenheit-und-innovation--2450478"
